package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.regex.*;
/** New mode isolation; pixel/claim/adopt chain is separately exercised by the integration fixture. */
public class RootUniquePendingWiringTest {
 private String source(String n)throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once",n+".java")).replace("\r\n","\n");}
 @Test public void uniqueChoicePrecedesEveryOldLiveChoice()throws Exception{String a=source("DormantCaptureConfirmationActivity");String choices=a.substring(a.indexOf("private void showCaptureChoices()"));assertTrue(choices.indexOf("RootUniqueRefinedScope.ACTIVE")<choices.indexOf("RootStatusRecoveryScope.ACTIVE"));assertTrue(choices.contains("this::confirmUniquePending"));String initial=a.substring(a.indexOf("private void confirmUniquePending()"),a.indexOf("private void confirmSelectedPending()"));assertTrue(initial.indexOf("boundedSpent=true;consumed=true")<initial.indexOf("confirmedUniquePending"));assertTrue(initial.contains("boundedIntent.bindRun(autonomousRun)"));assertTrue(initial.contains("NativeRewardCardSession.Phase.BEFORE,1,null"));}
 @Test public void allPriorLiveIssuersAreHardBlocked()throws Exception{String v=source("VisibleCaptureAuthority");Matcher m=Pattern.compile("static [\\w.<>]+ (issue\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(v);int count=0;while(m.find()){if(m.group(1).startsWith("issueUniquePending")||m.group(1).equals("issueProgressReadIntent")||m.group(1).equals("issueProgressReadFrame")||m.group(1).equals("issueProgressScanIntent")||m.group(1).equals("issueProgressScanFrame")||m.group(1).equals("issueProgressLocateIntent")||m.group(1).equals("issueProgressLocateFrame")||m.group(1).equals("issueCheckpointIntent")||m.group(1).equals("issueCheckpointFrame")||m.group(1).equals("issueProgressLocateIntent")||m.group(1).equals("issueProgressLocateFrame"))continue;assertTrue(m.group(1),m.group(2).contains("if(RootUniqueRefinedScope.ACTIVE)throw"));count++;}assertTrue(count>=15);}
 @Test public void allPriorRuntimeStartsAreHardBlocked()throws Exception{String v=source("CaptureSessionRuntime");Matcher m=Pattern.compile("(?m)^    static CaptureSessionRuntime (start\\w*)\\([^{}]*\\)\\s*\\{([^{}]*)").matcher(v);int count=0;while(m.find()){if(m.group(1).equals("startUniquePending")||m.group(1).equals("startProgressRead")||m.group(1).equals("startProgressScan")||m.group(1).equals("startCheckpointRead")||m.group(1).equals("startProgressLocate"))continue;assertTrue(m.group(1),m.group(2).contains("if(RootUniqueRefinedScope.ACTIVE)throw"));count++;}assertTrue(count>=10);}
 @Test public void intentAndCompletionRequireExactImmutableMode()throws Exception{String i=source("RootBoundedBusinessIntent"),r=source("CaptureSessionRuntime");assertTrue(i.contains("private final boolean live,selectedPending,uniquePending"));assertTrue(i.contains("exact.uniquePendingOnly()!=uniquePending"));assertTrue(i.contains("a==null||!a.uniquePending||a.selectedPending"));assertTrue(r.contains("r.uniquePendingOnly()!=intent.uniquePending()||o.uniquePendingOnly()!=intent.uniquePending()"));assertTrue(r.contains("RootUniqueRefinedScope.store(activity.getNoBackupFilesDir().toPath(),cardPhase,boundedAttempt)"));}
 @Test public void uniqueProofCannotFallThroughToLegacyAcceptance()throws Exception{String r=source("CaptureSessionRuntime");int start=r.indexOf("if(observation.uniquePendingOnly())"),end=r.indexOf("if(observation.selectedPendingOnly())",start);String unique=r.substring(start,end);assertTrue(unique.contains("if(observation.uniqueProofReady()&&(observation.status()==LiveRewardCardObservation.Status.OBSERVED"));assertTrue(unique.contains("||observation.status()==LiveRewardCardObservation.Status.SECTION_COMPLETE_SKIP))return BoundedCompletion.Disposition.POSITIVE;"));assertFalse(unique.contains("Status.HOLD"));assertTrue(unique.contains("explicitUnpresented"));assertTrue(unique.contains(":null"));assertFalse(unique.contains("currentCards"));assertTrue(r.contains("preparedObservation.uniqueEvidenceSummary()"));}
 @Test public void sameFrameAndResourceGuardsRemain()throws Exception{String r=source("CaptureSessionRuntime");for(String s:new String[]{"preparedObservation.matches(preparedCapture)","rootPreflightSourceConfirmed&&resources&&rootCurrent()","acceptPreparedAfterCleanup(preparedCapture,preparedObservation,completion","rootResourcesClosed(result)&&autonomousRun.resourcesKnownClosed()","runtime.released&&runtime.reportFinal","now>=p.phaseDeadline()"})assertTrue(s,r.contains(s));String i=source("RootBoundedBusinessIntent");assertTrue(i.contains("deadline!=phaseEnds[i]"));assertTrue(i.contains("Distinct candidate owner required"));}
 @Test public void navigationUsesOnlyNewScopeWithOriginalBudget()throws Exception{String n=source("ReviewBingNavigation");int s=n.indexOf("static ReviewBingNavigation forUniquePending"),e=n.indexOf("static ReviewBingNavigation forSelectedPending",s);String factory=n.substring(s,e);assertTrue(factory.contains("RootUniqueRefinedScope.current"));assertFalse(factory.contains("RootSelectedPendingScope.current"));assertTrue(factory.contains("selectedPendingNavigation=true;reader.uniquePendingNavigation=true"));assertTrue(n.contains("uniquePendingNavigation?RootUniqueRefinedScope.current"));assertFalse(factory.contains("PAIRS.set"));}
 @Test public void disclosureBoundsInputAndSuccessAnchoredDelay()throws Exception{String u=source("RootCaptureUi");String unique=u.substring(u.indexOf("UNIQUE_PENDING_EXPLANATION"),u.indexOf("static void uniquePendingChoice"));for(String text:new String[]{"v38","05:20 至 07:00","原生点击命令成功确认后","至少5秒","调度策略，不是完成证明","仍受原180秒限制且不续期","不得答题、填写、登录、授权、付费、安装或分享","本轮已消费A/B同族、Quote、Puzzle、签到禁止自动重复","最多6帧"})assertTrue(text,unique.contains(text));assertTrue(u.contains("boundedReport="));assertTrue(u.contains("6499)/6500"));}
 @Test public void fixtureIntentIsNonliveAndOldIssuersRejectIt(){var e=new RealCaptureClaim.ProcessEpoch();var i=VisibleCaptureAuthority.fixtureUniquePendingIntent(new Object(),new Object(),e,new Object(),1000,()->RootUniqueRefinedScope.STARTS_UTC+1000);assertTrue(i.uniquePending());assertFalse(i.selectedPending());assertFalse(i.live());assertTrue(i.current(1000));assertFalse(i.current(i.sessionEnd()));try{VisibleCaptureAuthority.fixtureSelectedPendingGrant(i,NativeRewardCardSession.Phase.BEFORE,1,e,new Object(),1000,2000,null);fail();}catch(SecurityException expected){}try{VisibleCaptureAuthority.fixtureBoundedGrant(i,NativeRewardCardSession.Phase.BEFORE,1,e,new Object(),1000,2000,null);fail();}catch(SecurityException expected){}i.cancel();assertFalse(i.current(1000));}
 @Test public void activeUniqueRoutingUsesRefinedScopeOnly()throws Exception{for(String n:new String[]{"CaptureSessionRuntime","DormantCaptureConfirmationActivity","VisibleCaptureAuthority","RootBoundedBusinessIntent","ReviewBingNavigation"}){String a=source(n);assertTrue(n,a.contains("RootUniqueRefinedScope"));assertFalse(n,a.contains("RootUniquePendingScope"));}assertTrue(source("CaptureSessionRuntime").contains("UNIQUE_REFINED_V38"));String u=source("RootCaptureUi");assertTrue(u.contains("安全匹配诊断不包含OCR原文"));assertTrue(u.contains("不改写旧回执"));}
}
